<span class="line">           <span class="token function">calc</span><span class="token punctuation">(</span>50% - 50% * <span class="token function">cos</span><span class="token punctuation">(</span><span class="token function">var</span><span class="token punctuation">(</span>--_v<span class="token punctuation">)</span> * 3.6deg<span class="token punctuation">)</span><span class="token punctuation">)</span> of 50% large cw<span class="token punctuation">,</span></span>
